import json,re,html,xml.etree.ElementTree as ET
from pathlib import Path
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json'))
def plain(v): return re.sub(r'\\s+',' ',html.unescape(re.sub(r'<["'^>]+>'"',' ',v))).strip()
assert len(a)==len(s)==12
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
seen=set(); counts={}; nc=ne=0
for so,an in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert an[k]==so[k],(an['number'],k)
 key=an['code_id']+'|'+an['source_id']; assert key not in seen; seen.add(key)
 assert an['status']=='rewrite_draft'
 assert an['reason'] and an['review_notes'] and an['proposed_xml']
 root=ET.fromstring('<root>'+an['proposed_xml']+'</root>')
 for el in list(root.iter())[1:]:
  assert el.tag in allowed,(an['number'],el.tag)
  for k,v in el.attrib.items(): assert k in ['rowspan','colspan'] and v.isdigit()
 if so.get('benefit_check_required'): assert len(an['benefit_review'])>=100
 impact=an['substantive_impact']; assert impact['version']==1 and impact['classification'] in classes
 for k in ['assessment','scope_limitations','new_burdens_review']: assert len(impact[k])>=40
 counts[impact['classification']]=counts.get(impact['classification'],0)+1
 for e in impact['effects']:
  assert set(e)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
  assert e['kind'] in kinds and e['unit'] in units
  assert re.fullmatch(r'[a-z][a-z0-9-]{5,95}',e['measure_id'])
  assert all(isinstance(v,str) and v for v in e.values())
  assert len(e['source_quote'])>=12 and e['source_quote'] in plain(so['source_xml'])
  assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in plain(an['proposed_xml'])
  ne+=1
 req=r['requirements'][key]; checks=an['reference_checks']
 assert len(req)==len(checks) and set(req)=={c['target_key'] for c in checks}
 for c in checks:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256']
  assert len(c['assessment'])>=80
  nc+=1
 if an.get('change_type')=='normative_reduction':
  assert an['reform_policy_id']=='editorial_direction_2026_10_19'
  assert an['removed_provisions'] and all(len(x)>=30 for x in an['removed_provisions'])
 if impact['classification']=='mixed': assert any(e['kind'] in ['obligation_added','complexity_added','tax_increased','deadline_increased'] for e in impact['effects'])
 assert 'source_companions' not in so and 'sru_context' not in so
print(json.dumps({'articles':len(a),'reference_checks':nc,'effects_with_exact_quotes':ne,'classifications':counts,'xml_and_required_fields':'ok','benefit_reviews':'ok','identifiers_and_view_hashes':'ok','legal_validation_claimed':False},ensure_ascii=False,indent=2))
PY"

